function i(t){if(!t)return"—";const r=new Date(t);return Number.isNaN(r.getTime())?String(t):new Intl.DateTimeFormat("en-US",{month:"long",day:"numeric",year:"numeric"}).format(r)}function m(t,r="—"){if(!t)return r;const n=new Date(t);return Number.isNaN(n.getTime())?String(t):n.toLocaleString("en-PH",{month:"short",day:"numeric",year:"numeric",hour:"2-digit",minute:"2-digit"})}function e(t,r="—"){if(!t)return r;const n=new Date(t);return Number.isNaN(n.getTime())?String(t):new Intl.DateTimeFormat("en-US",{month:"short",day:"numeric",year:"numeric"}).format(n)}function a(t){return`PHP ${Number(t||0).toLocaleString("en-PH",{minimumFractionDigits:2,maximumFractionDigits:2})}`}function o(t){return Number(t||0).toLocaleString("en-PH",{minimumFractionDigits:2,maximumFractionDigits:2})}function u(t,r="—"){return e(t,r)}export{u as a,e as b,o as c,m as d,a as e,i as f};
